    "name": "theme_info",
    "theme_name": "Radaelli Swimwear",
    "theme_author": "Radaelli Swimwear",
    "theme_version": "1.0.0",
    "theme_support_email": "info@radaelliswimwear.com",
    "theme_documentation_url": "https://github.com/radaelliswimwear-rgb/rada"
  },
  {
    "name": "Brand",
    "settings": [
      {
        "type": "image_picker",
        "id": "logo",
        "label": "Logo"
      },
      {
        "type": "image_picker",
        "id": "favicon",
        "label": "Favicon"
      },
      {
        "type": "image_picker",
        "id": "social_share_image",
        "label": "Imagen para compartir (redes y buscadores)",
