      {
        "type": "color",
        "id": "color_background",
        "label": "Fondo base",
        "default": "#FFFFFF"
      },
      {
        "type": "color",
        "id": "color_background_soft",
        "label": "Fondo suave (cards, secciones alternas)",
        "default": "#F7F4EF"
      },
      {
        "type": "color",
        "id": "color_text",
        "label": "Texto principal",
        "default": "#171717"
      },
      {
        "type": "color",
        "id": "color_text_secondary",
        "label": "Texto secundario",
        "default": "#666666"
      },
      {
        "type": "color",
        "id": "color_ink",
        "label": "Acento principal (botones, CTA)",
        "default": "#000000",
        "info": "Corresponde a --color-brand-crimson en el sitio actual -- el nombre original sugiere rojo, el valor real es negro. Ver design-tokens.md."
      },
      {
        "type": "color",
        "id": "color_nude",
        "label": "Nude (acento secundario)",
        "default": "#D6C5AE"
      },
      {
        "type": "color",
        "id": "color_nude_hover",
        "label": "Nude (hover)",
        "default": "#C3AE8E"
      },
      {
        "type": "color",
        "id": "color_border",
        "label": "Bordes",
        "default": "#E7E7E7"
      }
    ]
  },
