        "type": "range",
        "id": "page_width",
        "label": "Ancho máximo de contenedor (px)",
        "min": 960,
        "max": 1600,
        "step": 20,
        "default": 1280,
        "info": "Equivalente real a max-w-7xl del sitio actual."
      }
    ]
  },
  {
    "name": "Header",
    "settings": [
      {
        "type": "checkbox",
        "id": "enable_sticky_header",
        "label": "Header fijo al hacer scroll",
        "default": true,
        "info": "EXACT: el header real es sticky (sticky top-0) y cambia de fondo/blur al pasar 8px de scroll (components/layout/navbar/index.tsx) -- replicado en la Fase 02C."
      },
      {
        "type": "range",
        "id": "logo_width",
        "label": "Ancho del logo (px, desktop)",
        "min": 120,
        "max": 320,
        "step": 8,
        "default": 224,
        "info": "EXACT: w-56 (224px) real del header actual."
      },
      {
        "type": "checkbox",
        "id": "show_wishlist_icon",
        "label": "Mostrar ícono de favoritos en el header",
        "default": true
