      {
        "type": "checkbox",
        "id": "cart_show_compare_at",
        "label": "Mostrar el precio anterior tachado",
        "default": false,
        "info": "El carrito real no lo muestra. Los descuentos nativos de Shopify (automáticos o por código) se muestran siempre."
      },
      {
        "type": "header",
        "content": "Envío gratis"
      },
      {
        "type": "checkbox",
        "id": "free_shipping_rate_confirmed",
        "label": "La tarifa de envío gratis ya está configurada en Shopify",
        "default": false,
        "info": "Mientras esté apagado, el tema no promete envío gratis en ningún lado (banner, ficha, carrito). Encender solo cuando Shopify > Envío tenga una tarifa gratis para Colombia desde este mismo umbral."
      },
      {
        "type": "checkbox",
        "id": "cart_free_shipping_progress",
        "label": "Mostrar el progreso de envío gratis en el carrito",
        "default": false,
        "info": "Activar SOLO si Shopify tiene una tarifa de envío gratis con este mismo umbral. El theme no puede leer las tarifas: si no coinciden, el carrito prometería algo que el checkout no cumple."
      },
      {
        "type": "number",
        "id": "free_shipping_threshold",
        "label": "Umbral de envío gratis (en pesos, sin centavos)",
        "default": 299900,
        "info": "Valor real actual: 299900 = $299.900 (Settings.freeShippingThreshold del ecommerce). Lo usan el carrito, el banner promocional y la ficha, solo con la tarifa confirmada."
      }
    ]
